//! Zod pipe parity (zod 4, the default version): the pipe, its exceptions and
//! `validate`, compared with `fixtures/zod4/pipe.json` (generated by `fixtures/zod4/pipe.mjs`
//! with the real packages), plus the same flows over HTTP.

use corvis::common::pipe::{ArgumentMetadata, Metatype, ParamKind, PipeTransform};
use corvis::prelude::*;
use corvis::testing::{Test, request};
use corvis::zod_dto;
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CreateUserDto {
    pub email: String,
    pub password: String,
    pub role: String,
}

zod_dto!(
    CreateUserDto,
    z::strict_object! {
        email: z::email(),
        password: z::string().min(1),
        role: z::enum_(["admin", "user"]).default("user"),
    }
);

fn query_schema() -> z::Schema {
    z::object! {
        page: z::coerce::number().int().min(1.0).default(1),
        includeInactive: z::stringbool().optional(),
    }
    .into()
}

fn conflict() -> z::Schema {
    z::intersection(z::string().transform(|_| json!(1)), z::string().transform(|_| json!(2)))
}

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/zod4/pipe.json")).unwrap()
}

fn meta(kind: ParamKind, zod: Option<fn() -> &'static z::Schema>) -> ArgumentMetadata {
    ArgumentMetadata { kind, data: None, metatype: Metatype { name: "T", validator: None, zod } }
}

fn dto_meta() -> ArgumentMetadata {
    meta(ParamKind::Body, Some(<CreateUserDto as z::ZodDto>::schema))
}

/// `{ ok }` or `{ status, body }`, like the fixture.
fn outcome(r: Result<Value, HttpException>) -> Value {
    match r {
        Ok(v) => json!({ "ok": v }),
        Err(e) => json!({ "status": e.get_status(), "body": e.get_response() }),
    }
}

fn assert_same(name: &str, got: Value, fx: &Value) {
    let mut want = fx[name].clone();
    if let Some(o) = want.as_object_mut() {
        o.remove("name");
    }
    // Key order matters (it is the HTTP body).
    assert_eq!(serde_json::to_string(&got).unwrap(), serde_json::to_string(&want).unwrap(), "{name}");
}

#[corvis::test]
async fn zod_pipe_matches_fixture() {
    let fx = fixture();
    let dto_schema = <CreateUserDto as z::ZodDto>::schema().clone();
    let explicit = ZodValidationPipe::new(dto_schema.clone());
    let global = ZodValidationPipe::auto();

    let r = explicit.transform(json!({ "email": "a@b.co", "password": "x" }), &dto_meta()).await;
    assert_same("pipeSchemaOk", outcome(r), &fx);
    let r = explicit.transform(json!({ "email": "nope", "password": "", "extra": 1 }), &dto_meta()).await;
    assert_same("pipeSchemaFail", outcome(r), &fx);
    let r = global.transform(json!({}), &dto_meta()).await;
    assert_same("pipeDtoFail", outcome(r), &fx);
    // A missing body reaches the pipe as `null` and is validated as `undefined`.
    let r = global.transform(Value::Null, &dto_meta()).await;
    assert_same("pipeDtoUndefined", outcome(r), &fx);
    let r = global.transform(json!({ "a": 1 }), &meta(ParamKind::Body, None)).await;
    assert_same("pipeNoDto", outcome(r), &fx);

    let q = ZodValidationPipe::new(query_schema());
    let r = q.transform(json!({ "page": "3", "includeInactive": "yes" }), &meta(ParamKind::Query, None)).await;
    assert_same("pipeQueryOk", outcome(r), &fx);
    let r = q.transform(json!({ "page": "0", "includeInactive": "maybe" }), &meta(ParamKind::Query, None)).await;
    assert_same("pipeQueryFail", outcome(r), &fx);

    let r = ZodValidationPipe::new(conflict()).transform(json!("x"), &meta(ParamKind::Body, None)).await;
    assert_same("pipeThrown", outcome(r), &fx);

    let strict = z::create_zod_validation_pipe(z::ZodValidationPipeOptions::new().strict_schema_declaration(true));
    let r = strict.transform(json!({ "a": 1 }), &meta(ParamKind::Body, None)).await;
    assert_same("strictNoDto", outcome(r), &fx);

    let custom = z::create_zod_validation_pipe(z::ZodValidationPipeOptions::new().create_validation_exception(|e| {
        BadRequestException::new(json!({ "custom": true, "count": e.issues.len() }))
    }));
    let r = custom.transform(json!({}), &dto_meta()).await;
    assert_same("customException", outcome(r), &fx);

    let r = z::validate(&json!({ "email": 1 }), &dto_schema, None);
    assert_same("validateFail", outcome(r), &fx);
    let e = z::ZodValidationException::new(dto_schema.safe_parse(&json!({})).error.unwrap());
    assert_eq!(z::ZodValidationException::get_zod_error(&e).unwrap().issues.len(), 2);

    let dto = <CreateUserDto as z::ZodDto>::create(&json!({ "email": "a@b.co", "password": "x" })).unwrap();
    assert_eq!(dto.role, "user");

    let r = Err(z::ZodSerializationException::new(z::ZodError::new(Vec::new())));
    assert_same("serializationException", outcome(r), &fx);
}

#[derive(Debug, Deserialize)]
pub struct ListQuery {
    pub page: u32,
    #[serde(rename = "includeInactive")]
    pub include_inactive: Option<bool>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UserDto {
    pub id: u32,
    pub email: String,
}

zod_dto!(UserDto, z::object! { id: z::int(), email: z::email() });

#[controller("users")]
pub struct UsersController;

#[routes]
impl UsersController {
    #[post]
    fn create(&self, #[body] dto: CreateUserDto) -> CreateUserDto {
        dto
    }

    #[get]
    fn list(&self, #[query(ZodValidationPipe::new(query_schema()))] q: ListQuery) -> Value {
        json!({ "page": q.page, "includeInactive": q.include_inactive })
    }

    /// `@ZodSerializerDto(UserDto)`: extra keys are stripped from the response.
    #[get("me")]
    #[set_metadata(z::ZOD_SERIALIZER_DTO_OPTIONS, z::ZodSerializerDto::dto::<UserDto>())]
    fn me(&self) -> Value {
        json!({ "id": 1, "email": "a@b.co", "passwordHash": "x" })
    }

    /// `@UseZodGuard('body', CreateUserDto)`: validates, but the handler gets the raw body.
    #[post("guarded")]
    #[use_guards(z::ZodGuard::dto::<CreateUserDto>(z::ZodGuardSource::Body))]
    #[http_code(200)]
    fn guarded(&self, #[body] body: Value) -> Value {
        body
    }

    /// A response that does not match its DTO is a 500.
    #[get("broken")]
    #[set_metadata(z::ZOD_SERIALIZER_DTO_OPTIONS, z::ZodSerializerDto::dto::<UserDto>())]
    fn broken(&self) -> Value {
        json!({ "id": "x" })
    }
}

#[module(controllers = [UsersController])]
pub struct AppModule;

#[corvis::test]
async fn zod_pipe_over_http() {
    let fx = fixture();
    let module = Test::create_testing_module().import::<AppModule>().compile().await.unwrap();
    let mut app = module.create_corvis_application();
    app.use_global_pipes(ZodValidationPipe::auto());
    app.use_global_interceptors(z::ZodSerializerInterceptor::new());
    app.init().await.unwrap();
    let client = request(&app);

    client
        .post("/users")
        .json(&json!({ "email": "a@b.co", "password": "x" }))
        .send()
        .await
        .expect_status(201)
        .expect_json(json!({ "email": "a@b.co", "password": "x", "role": "user" }));
    let res = client.post("/users").json(&json!({ "email": "nope", "password": "", "extra": 1 })).send().await;
    res.expect_status(400);
    assert_eq!(res.json_value(), fx["pipeSchemaFail"]["body"]);
    let res = client.post("/users").send().await;
    res.expect_status(400);
    assert_eq!(res.json_value(), fx["pipeDtoUndefined"]["body"]);

    client.get("/users").send().await.expect_status(200).expect_json(json!({ "page": 1, "includeInactive": null }));
    client
        .get("/users")
        .query("page", "3")
        .query("includeInactive", "yes")
        .send()
        .await
        .expect_status(200)
        .expect_json(json!({ "page": 3, "includeInactive": true }));
    let res = client.get("/users").query("page", "0").query("includeInactive", "maybe").send().await;
    res.expect_status(400);
    assert_eq!(res.json_value(), fx["pipeQueryFail"]["body"]);

    client.post("/users/guarded").json(&json!({ "email": "a@b.co", "password": "x" })).send().await.expect_status(200);
    let res = client.post("/users/guarded").json(&json!({ "email": "nope", "password": "", "extra": 1 })).send().await;
    res.expect_status(400);
    assert_eq!(res.json_value(), fx["pipeSchemaFail"]["body"]);

    client.get("/users/me").send().await.expect_status(200).expect_json(json!({ "id": 1, "email": "a@b.co" }));
    let res = client.get("/users/broken").send().await;
    res.expect_status(500);
    assert_eq!(serde_json::to_string(&res.json_value()).unwrap(), r#"{"message":"Internal Server Error","statusCode":500}"#);
}
